import re

def calistir(program: str) -> any:
    """Küçük bir hesap dilini yorumlar ve son ifadenin değerini döndürür. eval, exec, compile, ast yasaktır."""
    lines = [line.split('#', 1)[0].strip() for line in program.splitlines() if line.strip() and not line.strip().startswith('#')]

    env = {}
    last_result = None

    # Fonksiyon tanımları (Standart kütüphane ve temel matematik fonksiyonları)
    def min(args):
        return min(args)
    def max(args):
        return max(args)
    def abs(x):
        return abs(x)

    token_regex = r'[a-zA-Z_][a-zA-Z0-9]*|\d+\.\d+|\d+|[+\-*/%**()]|[;,]' 

    def tokenize(expression):
        return re.findall(token_regex, expression)

    # Operatör öncelik seviyeleri (düşükten yükseğe)
    precedence = {
        '+': 1, '-': 1, 
        '*': 2, '/': 2, '%': 2, 
        '**': 3, 
        'unary_plus': 4, 'unary_minus': 4 
    }

    def apply_op(op, b, a):
        if op == '+': return a + b
        if op == '-': return a - b
        if op == '*': return a * b
        if op == '/': 
            if b == 0: raise ZeroDivisionError("Sıfıra bölme")
            return a / b
        if op == '%': return a % b
        if op == '**': return a ** b
        raise SyntaxError(f"Bilinmeyen operatör: {op}")

    def is_number(token):
        try:
            float(token)
            return True
        except ValueError: return False

    def parse_expression(tokens, env):
        # Bu kısım, Pratt Parser'ın temel mantığını taklit eder (Precedence Climbing)

        # Fonksiyon çağrısı kontrolü
        if tokens and tokens[0] in ['min', 'max', 'abs']:
            func_name = tokens.pop(0)
            tokens.pop(0) # '(' 
            args = []
            while tokens and tokens[0] != ')':
                args.append(parse_expression(tokens, env))
                if tokens and tokens[0] == ',':
                    tokens.pop(0) # ','
            tokens.pop(0) # ')'

            if func_name == 'min': return min(args)
            if func_name == 'max': return max(args)
            if func_name == 'abs': return abs(args[0])
            raise NameError(f"Bilinmeyen fonksiyon: {func_name}")

        # Atom (Sayı, Değişken)
        if tokens and (is_number(tokens[0]) or tokens[0] in env):
             token = tokens.pop(0)
             if is_number(token): return float(token)
             return env[token]

        # Tekli işaret ayrımı (Unary Minus/Plus) - Bu, token akışında kontrol edilmeli
        if tokens and (tokens[0] == '-' or tokens[0] == '+'):
            op = tokens.pop(0)
            # Tekli işaretin ardından bir atom beklenir
            if not tokens or not (is_number(tokens[0]) or tokens[0] in env or tokens[0] in ['min', 'max', 'abs']):
                 raise SyntaxError(f"Tekli işaret '{op}' ardından ifade bekleniyor.")
            # Negasyonlu/Pozitif değerin kendisini hesapla
            val = parse_expression(tokens, env)
            return -val if op == '-' else val

        raise SyntaxError(f"Sözdizimi hatası: Geçersiz ifade başlangıcı: {tokens[0]}")

    # Ana çalıştırma döngüsü
    for line in lines:
        line = line.strip()
        if not line: continue

        # 1. Atama Kontrolü
        if '=' in line and line.count('=') == 1:
            var_name, expression_str = [p.strip() for p in line.split('=', 1)]
            tokens = tokenize(expression_str)

            # Hesaplama
            try:
                current_value = parse_expression(tokens, env)
                env[var_name] = current_value
                last_result = current_value
            except Exception as e:
                # Hata yakalama (NameError, ZeroDivisionError, SyntaxError)
                raise e

        # 2. İfade Kontrolü
        else:
            tokens = tokenize(line)
            if not tokens: continue

            # Hesaplama
            try:
                last_result = parse_expression(tokens, env)
            except Exception as e:
                raise e

    return last_result

