    # Operatör öncelik seviyeleri
    precedence = {
        '+': 1, '-': 1, 
        '*': 2, '/': 2, '%': 2, 
        '**': 3
    }

    # Unary operatörler için özel kontrol (önceki/sonraki tokena bakılarak)
    def is_unary(token, prev_token):
        return token in ('+', '-') and (prev_token is None or prev_token in '([{,')

    # --- Shunting-Yard Algoritması (Infix -> RPN) ---
    def shunting_yard(tokens):
        output_queue = []
        operator_stack = []

        for i, token in enumerate(tokens):
            if token in env: # Değişken
                output_queue.append(token)
            elif is_number(token):
                output_queue.append(token)
            elif token in ['min', 'max', 'abs']: # Fonksiyon
                operator_stack.append(token)
            elif token == '(': 
                operator_stack.append(token)
            elif token == ')': 
                while operator_stack and operator_stack[-1] != '(': 
                    output_queue.append(operator_stack.pop())
                if not operator_stack or operator_stack[-1] != '(': raise SyntaxError("Eşleşmeyen parantez")
                operator_stack.pop() # '(' çıkar
            elif token in precedence:
                # Unary operatörler için özel öncelik/işlem gerekir. Basitleştirme için, şimdilik sadece binary kontrolü yapalım.
                while (operator_stack and operator_stack[-1] != '(' and 
                       precedence.get(operator_stack[-1], 0) >= precedence[token]):
                    output_queue.append(operator_stack.pop())
                operator_stack.append(token)
            elif token == ',':
                while operator_stack and operator_stack[-1] != '(': output_queue.append(operator_stack.pop())
            else:
