                if token in ('+', '-') and (i == 0 or tokens[i-1] in '([{,'):
                    # Unary işaretleri özel bir token olarak ele almalıyız, ancak basitlik için şimdilik atlıyoruz ve hesaplama aşamasında düzeltiyoruz.
